import{_ as r,o as t,c as o,ak as s,aI as i,aJ as n,aK as l,aL as a,aM as u,aN as p,aO as d}from"./chunks/framework.DveU0bjS.js";const P=JSON.parse('{"title":"Compiler un projet Unity","description":"","frontmatter":{},"headers":[],"relativePath":"05_CompilerProjetWebEtWindows.md","filePath":"05_CompilerProjetWebEtWindows.md","lastUpdated":1770148987000}'),c={name:"05_CompilerProjetWebEtWindows.md"};function g(m,e,b,f,v,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="compiler-un-projet-unity" tabindex="-1">Compiler un projet Unity <a class="header-anchor" href="#compiler-un-projet-unity" aria-label="Permalink to “Compiler un projet Unity”">​</a></h1><p>Une fois que vous avez terminé le développement de votre projet Unity, l&#39;étape suivante consiste à le compiler et à le mettre en ligne pour que d&#39;autres puissent y accéder. Voici un guide étape par étape pour compiler votre projet Unity et le publier en ligne avec GitHub Pages.</p><h2 id="etape-1-preparer-votre-projet-unity-et-choisir-les-scenes" tabindex="-1">Étape 1 : Préparer votre projet Unity et choisir les scènes <a class="header-anchor" href="#etape-1-preparer-votre-projet-unity-et-choisir-les-scenes" aria-label="Permalink to “Étape 1 : Préparer votre projet Unity et choisir les scènes”">​</a></h2><p>Avant de compiler votre projet, assurez-vous que tout fonctionne correctement dans l&#39;éditeur Unity. Testez votre jeu ou application pour vous assurer qu&#39;il n&#39;y a pas de bugs majeurs. Il ne devrait pas y avoir de problèmes de performance ou d&#39;erreurs critiques qui empêcheraient le bon fonctionnement de votre projet. Poussez également toutes les modifications finales dans votre dépôt GitHub.</p><p>Pour choisir quelles scènes seront incluses dans le build, il faut se rendre dans le menu <strong>File &gt; Build Profile &gt; Scene List</strong>. Là, vous verrez une liste des scènes dans le build. Pour choisir les scènes à inclure, cliquez sur le bouton<strong>Add Open Scene</strong> pour ajouter la scène actuelle à la liste ou glissez-déposez des fichiers de scène du panneau <strong>Project</strong>. Vous pouvez aussi modifier la séquence de scènes : <strong>la scène numéro 0 servira de point de départ du jeu</strong>.</p><p><img src="'+i+'" alt=""></p><h2 id="etape-2a-configurer-les-parametres-de-build-pour-web" tabindex="-1">Étape 2A : Configurer les paramètres de build pour <strong>web</strong> <a class="header-anchor" href="#etape-2a-configurer-les-parametres-de-build-pour-web" aria-label="Permalink to “Étape 2A : Configurer les paramètres de build pour web”">​</a></h2><ol><li>Ouvrez votre projet Unity.</li><li>Allez dans le menu <strong>File</strong> &gt; <strong>Build Profiles</strong>.</li><li>Sélectionnez <strong>Web</strong> comme plateforme de build. Si vous ne voyez pas cette option, vous devrez peut-être installer le module <strong>WebGL Build Support</strong> via le Unity Hub.</li><li>Cliquez sur <strong>Switch Platform</strong> pour basculer vers la plateforme WebGL si ce n&#39;est pas déjà fait.</li><li>Configurez les paramètres de build selon vos besoins (résolution, qualité, etc.). Vous pouvez également ajuster les paramètres avancés dans <strong>Edit</strong> &gt; <strong>Project Settings</strong> &gt; <strong>Player</strong>.</li><li>Réglez la résolution de votre application WebGL en fonction de vos besoins. Vous pouvez choisir une résolution fixe ou permettre à l&#39;application de s&#39;adapter à la taille de la fenêtre du navigateur.</li><li>Dans le cas du WebGL, assurez-vous que l&#39;option <strong>Compression Format</strong> est définie sur <strong>Disabled</strong> pour éviter les problèmes de chargement sur GitHub Pages et que le mode ce soit compatible avec Itch.io.</li></ol><p><img src="'+n+'" alt="Compilation pour WebGL"></p><p><img src="'+l+'" alt="Réglages de la résolution"></p><p><img src="'+a+'" alt="Désactivez la compression pour déployer sur Github Pages et Itch.io"></p><h2 id="etape-2b-configurer-les-parametres-de-build-pour-windows" tabindex="-1">Étape 2B : Configurer les paramètres de build pour <strong>Windows</strong> <a class="header-anchor" href="#etape-2b-configurer-les-parametres-de-build-pour-windows" aria-label="Permalink to “Étape 2B : Configurer les paramètres de build pour Windows”">​</a></h2><ol><li>Ouvrez votre projet Unity.</li><li>Sélectionnez <strong>Windows</strong> comme plateforme de build. Si vous ne voyez pas cette option, vous devrez peut-être installer le module <strong>Windows Build Support (IL2CPP)</strong> via le Unity Hub.</li><li>Cliquez sur <strong>Switch Platform</strong> pour basculer vers la plateforme Windows si ce n&#39;est pas déjà fait.</li><li>Configurer les paramètres du player dans <strong>Edit &gt; Project Settings &gt; Player</strong> ou en cliquant <strong>Build Profiles &gt; PlayerSettings</strong>. <ul><li><strong>Company Name</strong> : Choisissez un nom de créateur / équipe.</li><li><strong>Product Name</strong> : Nom du projet. Cette option change aussi le nom du fichier <code>.exe</code> (ex : <code>MonJeu.exe</code>).</li><li><strong>Resolution and Presentation &gt; Fullscreen Mode</strong> pour configurer le comportement de l&#39;écran du jeu. L&#39;option <strong>Windowed</strong> permet de configurer une taille défaut, par exemple.</li></ul></li><li><strong>Générer le build.</strong> Dans les Build Profiles, cliquez sur <strong>Build</strong> pour choisir un emplacement pour le dossier de sortie et générer le build. L&#39;option <strong>Build and Run</strong> utilise l&#39;emplacement antérieur.</li><li><strong>Vérifier le build généré</strong>. Ouvrez le dossier de sortie (ex : 📂<code>Builds/Windows</code>) et vérifiez que le fichier <code>.exe</code> et les sous-dossier nécessaires ont été créés (ex <code>Data</code>). Pour tester dans un autre PC ou emplacement, copiez le dossier de sortie entier et cliquez sur le fichier <code>.exe</code> pour exécuter le jeu.</li></ol><p><img src="'+u+'" alt=""></p><p><img src="'+p+'" alt=""></p><p><img src="'+d+'" alt=""></p>',16)])])}const j=r(c,[["render",g]]);export{P as __pageData,j as default};
